 <div class="panel" id="intro"><div class="introbox"><div class="eyebrow">A survival story · An uncharted archipelago</div><h1>THE<br><em>FIRST</em><br>SHORE</h1><p>The storm took the plane. The tide gave you back. Wake on Fairestatle, salvage what remains, and make the island answer one question: are you alone?</p><button class="startbtn" id="begin">Wake up on the island&nbsp; →</button><p class="controlsline"><b>WASD</b> move &nbsp; <b>SHIFT</b> sprint &nbsp; <b>E</b> gather &nbsp; <b>Q</b> craft &nbsp; <b>drag</b> to look</p></div></div>
 <div class="mobilecontrols"><button id="touchMove">MOVE</button><button id="touchAction">GATHER</button></div>
 <script type="module">
 import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.161.0/build/three.module.js';
-</script>
+const $=s=>document.querySelector(s), game=$('#game');
+const scene=new THREE.Scene(); scene.background=new THREE.Color(0x86b9b5); scene.fog=new THREE.FogExp2(0x91bbb3,.008);
+const camera=new THREE.PerspectiveCamera(61,innerWidth/innerHeight,.1,450);
+const renderer=new THREE.WebGLRenderer({antialias:true,powerPreference:'high-performance'}); renderer.setPixelRatio(Math.min(devicePixelRatio,1.7)); renderer.setSize(innerWidth,innerHeight); renderer.shadowMap.enabled=true; renderer.shadowMap.type=THREE.PCFSoftShadowMap; renderer.toneMapping=THREE.ACESFilmicToneMapping; renderer.toneMappingExposure=1.15; game.appendChild(renderer.domElement);
+scene.add(new THREE.HemisphereLight(0xc9f0e7,0x64513c,2.1));
+const sun=new THREE.DirectionalLight(0xffd5a0,3.2); sun.position.set(-45,70,30); sun.castShadow=true; sun.shadow.mapSize.set(1024,1024); sun.shadow.camera.left=-55;sun.shadow.camera.right=55;sun.shadow.camera.top=55;sun.shadow.camera.bottom=-55;scene.add(sun);
+const oceanMat=new THREE.MeshStandardMaterial({color:0x267d83,roughness:.27,metalness:.12,transparent:true,opacity:.93});
+const ocean=new THREE.Mesh(new THREE.PlaneGeometry(420,420,1,1),oceanMat);ocean.rotation.x=-Math.PI/2;ocean.position.y=-.12;ocean.receiveShadow=true;scene.add(ocean);
+const sandMat=new THREE.MeshStandardMaterial({color:0xd9c38f,roughness:.94}), grassMat=new THREE.MeshStandardMaterial({color:0x668954,roughness:1}), rockMat=new THREE.MeshStandardMaterial({color:0x75796b,roughness:.94}), woodMat=new THREE.MeshStandardMaterial({color:0x76513a,roughness:.9}), leafMat=new THREE.MeshStandardMaterial({color:0x416f48,roughness:.87,side:THREE.DoubleSide}), brightLeaf=new THREE.MeshStandardMaterial({color:0x6a9855,roughness:.9,side:THREE.DoubleSide});
+function heightAt(x,z){const r=Math.hypot(x,z), edge=Math.max(0,1-r/37); return r<37? .12+Math.pow(edge,.68)*4.5+Math.sin(x*.17+z*.08)*.18+Math.cos(z*.2)*.12:-.12;}
+function island(rx=37,rz=32,cx=0,cz=0,scale=1){const seg=96, rings=20, pos=[],idx=[],col=[];for(let j=0;j<=rings;j++){const v=j/rings;for(let i=0;i<=seg;i++){const a=i/seg*Math.PI*2, x=cx+Math.cos(a)*rx*v,z=cz+Math.sin(a)*rz*v, y=heightAt(x-cx,z-cz)*scale;pos.push(x,y,z);let color=new THREE.Color(v>.84?0xd9c38f:v>.70?0x9b9d65:0x668954);color.multiplyScalar(.94+Math.random()*.12);col.push(color.r,color.g,color.b);if(i<seg&&j<rings){let n=j*(seg+1)+i;idx.push(n,n+seg+1,n+1,n+1,n+seg+1,n+seg+2)}}}const g=new THREE.BufferGeometry();g.setAttribute('position',new THREE.Float32BufferAttribute(pos,3));g.setAttribute('color',new THREE.Float32BufferAttribute(col,3));g.setIndex(idx);g.computeVertexNormals();const m=new THREE.Mesh(g,new THREE.MeshStandardMaterial({vertexColors:true,roughness:1,flatShading:false}));m.receiveShadow=true;scene.add(m);return m;}
+island(); island(14,11,76,-40,.76); island(18,15,-79,-60,.88); island(12,10,35,99,.8);
+// Reefs and the far-off island chain give the horizon scale.
+for(let i=0;i<34;i++){const a=i/34*Math.PI*2,r=42+Math.random()*8,x=Math.cos(a)*r,z=Math.sin(a)*r;const reef=new THREE.Mesh(new THREE.SphereGeometry(1,8,6),new THREE.MeshStandardMaterial({color:i%2?0x4c8f83:0x6e9a80,roughness:1}));reef.scale.set(2+Math.random()*3,.45,1.4+Math.random()*2);reef.position.set(x,-.3,z);scene.add(reef)}
+// Island flora: tapered trunks and curved leaf blades, deliberately low-poly but organic.
+const resources=[];
+function makePalm(x,z){let y=heightAt(x,z);const group=new THREE.Group();group.position.set(x,y,z);group.rotation.y=Math.random()*6.28;scene.add(group);const lean=new THREE.Vector3((Math.random()-.5)*.8,0,(Math.random()-.5)*.8);const trunk=new THREE.Mesh(new THREE.CylinderGeometry(.19,.34,5.1,9,4),woodMat);trunk.position.set(lean.x*1.3,2.4,lean.z*1.3);trunk.rotation.z=-lean.x*.18;trunk.rotation.x=lean.z*.18;trunk.castShadow=true;group.add(trunk);for(let n=0;n<8;n++){const a=n*Math.PI/4+Math.random()*.2;const leaf=new THREE.Mesh(new THREE.ConeGeometry(.42,4.2,5,1,true),n%2?leafMat:brightLeaf);leaf.position.set(lean.x*2.7,4.9,lean.z*2.7);leaf.rotation.z=Math.PI/2+Math.sin(a)*.52;leaf.rotation.y=a;leaf.castShadow=true;group.add(leaf)}const coc=new THREE.Mesh(new THREE.SphereGeometry(.22,8,7),new THREE.MeshStandardMaterial({color:0x826245}));coc.position.set(lean.x*2.7,4.45,lean.z*2.7);group.add(coc);resources.push({group,type:'tree',name:'Palm tree',x,z,hp:3,visible:true});}
+function makeRock(x,z){let y=heightAt(x,z);const g=new THREE.DodecahedronGeometry(.72+Math.random()*.45,0);const m=new THREE.Mesh(g,rockMat);m.position.set(x,y+.35,z);m.scale.set(1.3,.85,1);m.rotation.set(Math.random(),Math.random(),Math.random());m.castShadow=true;m.receiveShadow=true;scene.add(m);resources.push({mesh:m,type:'rock',name:'Stone outcrop',x,z,hp:2,visible:true});}
+function makeLoot(x,z,kind='wood'){const m=new THREE.Mesh(new THREE.BoxGeometry(kind==='wood'?1.5:.65,.35,.4),kind==='wood'?woodMat:kind==='vine'?new THREE.MeshStandardMaterial({color:0x788143}):new THREE.MeshStandardMaterial({color:0x9c6d45}));m.position.set(x,heightAt(x,z)+.23,z);m.rotation.y=Math.random()*Math.PI;m.castShadow=true;scene.add(m);resources.push({mesh:m,type:kind,name:kind==='wood'?'Driftwood':kind==='vine'?'Beach vine':kind==='coconut'?'Coconut':'Wreckage',x,z,hp:1,visible:true});}
+for(let i=0;i<44;i++){let a=Math.random()*Math.PI*2,r=8+Math.random()*25,x=Math.cos(a)*r,z=Math.sin(a)*r;if(heightAt(x,z)>.25)makePalm(x,z)}
+for(let i=0;i<24;i++){let a=Math.random()*Math.PI*2,r=5+Math.random()*31,x=Math.cos(a)*r,z=Math.sin(a)*r;if(heightAt(x,z)>.3)makeRock(x,z)}
+for(let i=0;i<8;i++){const x=-10+Math.random()*19,z=15+Math.random()*9;makeLoot(x,z,'wood')}for(let i=0;i<4;i++){const x=-10+Math.random()*19,z=16+Math.random()*10;makeLoot(x,z,i%2?'vine':'coconut')}
+// Plane wreckage and readable survivor note on the arrival beach.
+const wreck=new THREE.Group();wreck.position.set(3,heightAt(3,22)+.1,22);wreck.rotation.y=-.42;scene.add(wreck);const fus=new THREE.Mesh(new THREE.CylinderGeometry(.7,.88,7,10,1,true),new THREE.MeshStandardMaterial({color:0x59645f,metalness:.55,roughness:.56,side:THREE.DoubleSide}));fus.rotation.z=Math.PI/2;fus.position.y=1.05;fus.castShadow=true;wreck.add(fus);for(const s of [-1,1]){const wing=new THREE.Mesh(new THREE.BoxGeometry(4,.12,1.5),new THREE.MeshStandardMaterial({color:0x70766d,metalness:.35}));wing.position.set(s*1.1,1.2,0);wing.rotation.z=s*.13;wreck.add(wing)}
+const noteObj=new THREE.Mesh(new THREE.BoxGeometry(.48,.04,.65),new THREE.MeshStandardMaterial({color:0xe9dfbd}));noteObj.position.set(-2,heightAt(-2,19)+.2,19);noteObj.rotation.y=.4;noteObj.castShadow=true;scene.add(noteObj);resources.push({mesh:noteObj,type:'note',name:'Survivor note',x:-2,z:19,hp:1,visible:true});
