// Protagonist silhouette, with a bright salvage jacket for readability at a distance.
const player=new THREE.Group();scene.add(player);const body=new THREE.Mesh(new THREE.CapsuleGeometry(.43,.88,4,8),new THREE.MeshStandardMaterial({color:0xb76f48,roughness:.82}));body.position.y=1.02;body.castShadow=true;player.add(body);const head=new THREE.Mesh(new THREE.SphereGeometry(.26,12,10),new THREE.MeshStandardMaterial({color:0xc89b75}));head.position.y=1.85;head.castShadow=true;player.add(head);const pack=new THREE.Mesh(new THREE.BoxGeometry(.46,.52,.25),new THREE.MeshStandardMaterial({color:0x344c47}));pack.position.set(0,1.14,-.38);pack.castShadow=true;player.add(pack);player.position.set(0,heightAt(0,18),18);
let yaw=0,pitch=.12,started=false,isSwimming=false,diving=false,raftBuilt=false,axeBuilt=false,fireBuilt=false,elapsed=0,toastTimer=0,nearest=null,mouseDown=false,lastX=0,lastY=0;
const stats={health:100,stamina:100,hunger:100,thirst:100,oxygen:100};const bag={wood:0,stone:0,vine:0,coconut:0,fish:0};
// Simple island residents: passive beach crabs and a territorial boar with idle / alert / charge states.
const animals=[];
function creature(x,z,kind){const g=new THREE.Group();g.position.set(x,heightAt(x,z),z);scene.add(g);let mat=new THREE.MeshStandardMaterial({color:kind==='boar'?0x584438:0xc17a45,roughness:.94});const shell=new THREE.Mesh(kind==='boar'?new THREE.SphereGeometry(.65,10,8):new THREE.SphereGeometry(.34,9,7),mat);shell.position.y=kind==='boar'?.58:.3;shell.scale.set(kind==='boar'?1.25:.9,kind==='boar'?.78:.65,kind==='boar'?1.5:1.15);shell.castShadow=true;g.add(shell);if(kind==='boar'){for(let i=0;i<4;i++){const leg=new THREE.Mesh(new THREE.CylinderGeometry(.09,.08,.42,6),mat);leg.position.set(i<2?-.38:.38,.23,i%2?-.4:.4);g.add(leg)}}animals.push({group:g,x,z,kind,state:'idle',seed:Math.random()*10});}
creature(13,8,'boar');creature(-16,2,'boar');for(let i=0;i<7;i++)creature(-25+Math.random()*50,-18+Math.random()*30,'crab');
// Crafting recipes form the starter survival progression.
const recipes=[{id:'axe',name:'Stone axe',icon:'🪓',desc:'A crude edge for felling palms. Trees yield timber and vines.',cost:{wood:2,stone:2},once:true},{id:'fire',name:'Beach campfire',icon:'🔥',desc:'A safe place to cook and warm up after a long swim.',cost:{wood:3,stone:1},once:true},{id:'raft',name:'Reef skiff',icon:'🛶',desc:'A lashed driftwood raft. Sail toward the islands beyond the reef.',cost:{wood:6,vine:3},once:true},{id:'drink',name:'Coconut water',icon:'🥥',desc:'Drink a coconut to restore thirst and a little hunger.',cost:{coconut:1},once:false}];
function have(cost){return Object.entries(cost).every(([k,v])=>bag[k]>=v)}function costs(cost){return Object.entries(cost).map(([k,v])=>`${v} ${k}`).join(' · ')}
function drawRecipes(){const root=$('#recipes');root.innerHTML='';for(const r of recipes){const made=r.id==='axe'?axeBuilt:r.id==='fire'?fireBuilt:r.id==='raft'?raftBuilt:false;const box=document.createElement('div');box.className='recipe';box.innerHTML=`<div style="font-size:22px;margin-bottom:8px">${r.icon}</div><h3>${r.name}${made?' · made':''}</h3><p>${r.desc}<br><span style="color:#d5c795">${costs(r.cost)}</span></p><button ${!have(r.cost)||made&&r.once?'disabled':''}>${r.id==='drink'?'Use':'Craft'}</button>`;box.querySelector('button').onclick=()=>craft(r);root.appendChild(box)}}
function craft(r){if(!have(r.cost))return;for(const [k,v] of Object.entries(r.cost))bag[k]-=v;if(r.id==='axe'){axeBuilt=true;toast('Stone axe crafted · palms now yield timber');}if(r.id==='fire'){fireBuilt=true;buildCampfire();toast('Campfire placed on the shore');}if(r.id==='raft'){raftBuilt=true;makeRaft();toast('Reef skiff ready · the archipelago awaits');}if(r.id==='drink'){stats.thirst=Math.min(100,stats.thirst+32);stats.hunger=Math.min(100,stats.hunger+8);toast('Fresh coconut water · thirst restored');}updateInventory();drawRecipes()}
function buildCampfire(){const g=new THREE.Group();g.position.set(player.position.x+2,heightAt(player.position.x+2,player.position.z),player.position.z+1);scene.add(g);const ring=new THREE.Mesh(new THREE.TorusGeometry(.7,.12,6,12),rockMat);ring.rotation.x=Math.PI/2;ring.position.y=.12;g.add(ring);const flame=new THREE.Mesh(new THREE.ConeGeometry(.28,.9,7),new THREE.MeshBasicMaterial({color:0xff9b42}));flame.position.y=.6;g.add(flame);const light=new THREE.PointLight(0xff9a4c,2,9);light.position.y=1;g.add(light)}
function makeRaft(){const raft=new THREE.Group();const mat=new THREE.MeshStandardMaterial({color:0x98704b,roughness:.88});for(let i=0;i<5;i++){const log=new THREE.Mesh(new THREE.CylinderGeometry(.2,.2,3.8,8),mat);log.rotation.z=Math.PI/2;log.position.set(0,.15,(i-2)*.48);log.castShadow=true;raft.add(log)}const mast=new THREE.Mesh(new THREE.CylinderGeometry(.08,.12,3,7),woodMat);mast.position.set(0,1.5,0);raft.add(mast);const sail=new THREE.Mesh(new THREE.PlaneGeometry(1.7,1.8),new THREE.MeshStandardMaterial({color:0xe1d7b6,side:THREE.DoubleSide}));sail.position.set(0,2.1,0);raft.add(sail);raft.position.set(player.position.x,0,player.position.z);scene.add(raft);}
function updateInventory(){ $('#woodcount').textContent=bag.wood;$('#stonecount').textContent=bag.stone;$('#vinecount').textContent=bag.vine;$('#coconutcount').textContent=bag.coconut; }
function toast(msg){const el=$('#toast');el.textContent=msg;el.classList.add('show');toastTimer=2.3}
function panel(id,open){$(id).classList.toggle('open',open)}
function setBar(id,value){const el=$(id);el.style.width=Math.max(0,value)+'%';el.style.background=value<25?'#d87958':'var(--mint)'}
function updateHud(){for(const k of ['health','stamina','hunger','thirst']){setBar('#'+k+'bar',stats[k]);$('#'+k+'val').textContent=Math.round(stats[k])}$('#oxygenbar').style.width=(isSwimming?stats.oxygen:100)+'%';$('#oxygenval').textContent=isSwimming?Math.round(stats.oxygen):'—';$('#statusword').textContent=stats.health<30?'CRITICAL':stats.thirst<30?'DEHYDRATED':isSwimming?'SUBMERGED':'STABLE';}
function interact(){if(!started)return;if(nearest){const r=nearest;if(r.type==='note'){r.visible=false;r.mesh.visible=false;panel('#notePanel',true);toast('Survivor note added to your journal');return}if(r.type==='tree'&&!axeBuilt){toast('Need a stone axe · press Q to see recipes');return}if(r.type==='tree'){bag.wood+=2;bag.vine+=1;r.hp--;toast(r.hp?'Palm felled · +2 timber, +1 vine':'Palm harvested · +2 timber, +1 vine');if(!r.hp){r.visible=false;r.group.visible=false}}else if(r.type==='rock'){bag.stone+=2;r.hp--;toast('Stone fractured · +2 stone');if(!r.hp){r.visible=false;r.mesh.visible=false}}else{bag[r.type]=(bag[r.type]||0)+1;r.visible=false;r.mesh.visible=false;toast(`Salvaged ${r.name.toLowerCase()} · +1`)}updateInventory();drawRecipes();checkObjective();return}if(isSwimming){if(diving){bag.fish++;stats.stamina=Math.max(0,stats.stamina-5);toast('Speared a reef fish · +1 fish')}else{diving=true;toast('Diving below the surface · watch your oxygen')}return}toast('Nothing within reach');}
function checkObjective(){if(!axeBuilt){$('#objectiveTitle').textContent='Make a foothold';$('#objectiveText').textContent=bag.wood>=2&&bag.stone>=2?'Enough salvage for a stone axe. Open fieldcraft with Q.':'Search the wreckage for driftwood and stones, then craft a stone axe.'}else if(!fireBuilt){$('#objectiveTitle').textContent='Make a foothold';$('#objectiveText').textContent='Craft a campfire to make a safe place to cook and recover.'}else if(!raftBuilt){$('#objectiveTitle').textContent='Beyond the reef';$('#objectiveText').textContent='Gather more driftwood and vines to craft a reef skiff.'}else{$('#objectiveTitle').textContent='The Three Lights';$('#objectiveText').textContent='Your skiff is ready. Head out to discover the neighboring islands.'}}

