 *{box-sizing:border-box}html,body{margin:0;width:100%;height:100%;overflow:hidden;background:#142b31;color:var(--ink);font-family:Inter,ui-sans-serif,system-ui,-apple-system,"Segoe UI",sans-serif}canvas{display:block;width:100%;height:100%;outline:none}#game{position:fixed;inset:0}#vignette{position:fixed;inset:0;pointer-events:none;background:radial-gradient(ellipse at center,transparent 35%,rgba(4,16,20,.32) 100%);z-index:2}.hud{position:fixed;z-index:4;pointer-events:none}.topline{top:22px;left:28px;display:flex;align-items:center;gap:14px}.brand{font-family:Georgia,serif;font-size:21px;letter-spacing:.13em;text-transform:uppercase}.brand small{display:block;font:10px/1.5 ui-sans-serif,sans-serif;letter-spacing:.23em;color:var(--mint)}.daytag{padding:8px 12px;border:1px solid var(--line);border-radius:3px;background:var(--glass);font-size:10px;letter-spacing:.12em;color:#d5dfd5}.stats{top:22px;right:26px;width:210px;padding:13px 15px;background:var(--glass);border:1px solid var(--line);border-radius:5px;backdrop-filter:blur(10px)}.stats-head{display:flex;justify-content:space-between;font-size:9px;letter-spacing:.15em;color:var(--muted);margin-bottom:10px}.stat{display:grid;grid-template-columns:58px 1fr 26px;gap:8px;align-items:center;margin:7px 0;font-size:10px;color:#dce7dc}.bar{height:4px;background:rgba(255,255,255,.13);overflow:hidden}.bar i{display:block;height:100%;width:80%;background:var(--mint);transition:width .2s,background .2s}.stat b{text-align:right;font-size:9px;color:#d0d9ce;font-weight:500}.objective{top:122px;left:28px;width:224px;padding:13px 14px;background:linear-gradient(90deg,rgba(13,30,31,.8),transparent);border-left:2px solid var(--gold)}.eyebrow{font-size:9px;letter-spacing:.2em;color:var(--gold);text-transform:uppercase}.objective strong{display:block;margin:6px 0 3px;font:17px Georgia,serif}.objective p{margin:0;color:#c0cec3;font-size:11px;line-height:1.55}.reticle{position:fixed;z-index:3;left:50%;top:50%;width:18px;height:18px;transform:translate(-50%,-50%);pointer-events:none;opacity:.72}.reticle:before,.reticle:after{content:"";position:absolute;background:rgba(246,246,226,.86)}.reticle:before{width:1px;height:18px;left:8px}.reticle:after{height:1px;width:18px;top:8px}.prompt{position:fixed;z-index:5;left:50%;top:calc(50% + 24px);transform:translateX(-50%);padding:8px 12px;background:rgba(6,18,21,.78);border:1px solid var(--line);font-size:11px;letter-spacing:.05em;opacity:0;transition:opacity .15s;white-space:nowrap;pointer-events:none}.prompt b{color:var(--gold)}.bottomleft{bottom:22px;left:26px;display:flex;gap:8px}.slot{width:44px;height:46px;background:var(--glass);border:1px solid var(--line);border-radius:4px;display:grid;place-items:center;position:relative;font-size:18px}.slot small{position:absolute;bottom:3px;right:5px;font-size:9px;color:#d5e0d4}.slot.active{border-color:var(--gold);box-shadow:0 0 18px rgba(237,199,131,.2)}.hint{bottom:27px;right:26px;color:#dae1d7;font-size:10px;letter-spacing:.08em;text-align:right}.hint span{color:var(--gold)}.compass{position:fixed;z-index:4;left:50%;top:26px;transform:translateX(-50%);font-size:10px;letter-spacing:.2em;color:#f1eddb;text-shadow:0 1px 5px #142b31}.toast{position:fixed;z-index:8;top:19%;left:50%;transform:translate(-50%,-10px);padding:10px 17px;background:rgba(12,27,28,.88);border:1px solid rgba(237,199,131,.4);font-size:12px;letter-spacing:.05em;opacity:0;transition:.35s;pointer-events:none}.toast.show{opacity:1;transform:translate(-50%,0)}
 .panel{position:fixed;z-index:10;inset:0;background:rgba(5,15,18,.72);backdrop-filter:blur(8px);display:none;align-items:center;justify-content:center}.panel.open{display:flex}.card{width:min(720px,92vw);max-height:86vh;overflow:auto;background:linear-gradient(145deg,rgba(22,42,40,.98),rgba(12,26,29,.98));border:1px solid rgba(218,227,208,.2);box-shadow:0 24px 80px #061013;padding:32px}.cardhead{display:flex;justify-content:space-between;align-items:flex-start;border-bottom:1px solid var(--line);padding-bottom:17px;margin-bottom:20px}.card h2{font:30px Georgia,serif;margin:4px 0}.card p{color:#b6c4ba;font-size:13px;line-height:1.6}.close{background:none;color:#dce6db;border:1px solid var(--line);padding:7px 12px;cursor:pointer}.recipes{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.recipe{border:1px solid var(--line);padding:15px;background:rgba(255,255,255,.025);min-height:145px}.recipe h3{margin:0 0 6px;font:17px Georgia,serif}.recipe p{font-size:11px;margin:0 0 12px}.recipe button,.startbtn{background:var(--mint);color:#152a29;border:0;padding:10px 12px;font-weight:700;letter-spacing:.06em;cursor:pointer;font-size:10px;text-transform:uppercase}.recipe button:disabled{opacity:.35;cursor:not-allowed}.note{font:17px/1.8 Georgia,serif;color:#e5e2ce!important;padding:16px 22px;background:rgba(237,199,131,.06);border-left:2px solid var(--gold)}
-#intro{z-index:20;background:linear-gradient(180deg,rgba(6,18,25,.35),rgba(7,22,25,.92)),radial-gradient(ellipse at 68% 42%,#c68c5c 0,#294d4b 38%,#142b31 78%);display:flex}.introbox{width:min(620px,90vw);margin-left:8vw;align-self:flex-end;padding-bottom:12vh}.introbox .eyebrow{font-size:10px}.introbox h1{font:clamp(48px,8vw,88px)/.87 Georgia,serif;font-weight:400;letter-spacing:-.04em;margin:19px 0 20px}.introbox h1 em{color:var(--gold);font-weight:400}.introbox p{max-width:440px;color:#d4dfd4;line-height:1.7;font-size:14px}.introbox .startbtn{margin-top:15px;padding:15px 22px;font-size:11px}.controlsline{font-size:10px!important;letter-spacing:.08em;color:#aabbb0!important;margin-top:22px}.controlsline b{color:var(--gold);font-weight:500}.mobilecontrols{display:none;position:fixed;z-index:6;inset:auto 16px 20px;justify-content:space-between;pointer-events:none}.mobilecontrols button{pointer-events:auto;background:rgba(8,24,27,.56);color:white;border:1px solid #ffffff44;border-radius:50%;width:56px;height:56px;font-size:12px;backdrop-filter:blur(6px)}@media(max-width:700px){.topline{top:12px;left:12px}.brand{font-size:16px}.stats{top:12px;right:10px;width:155px;padding:9px}.objective{top:95px;left:12px;width:190px;padding:10px}.hint{display:none}.bottomleft{bottom:12px;left:12px}.slot{width:38px;height:40px}.compass{top:66px}.mobilecontrols{display:flex}.recipes{grid-template-columns:1fr}.card{padding:22px}.introbox{margin-left:7vw;padding-bottom:8vh}}
